$ErrorActionPreference='Stop'
$name='BasementHypervisor-SimcenterCapture'
$action=New-ScheduledTaskAction -Execute 'powershell.exe' -Argument '-WindowStyle Hidden -NoProfile -EncodedCommand '
$principal=New-ScheduledTaskPrincipal -UserId 'cadadmin' -LogonType Interactive
Register-ScheduledTask -TaskName $name -Action $action -Principal $principal -Force | Out-Null
Start-ScheduledTask -TaskName $name
Write-Output 'Capture task started'
